def test_runtime_fail_closed_target_relationship_authority():
 s=read('scripts/online/m271_targeting_relationship_authority_runtime.gd')
 for t in ['bind_combat','ingest_server_targeting_snapshot','ingest_server_target_verdict','stage_target_intent','local_target_hint','targeting_revision','relationship_state','aggro_state','zone_state','pvp_state','protection_state','invalidate_from_world_resync']: assert t in s
