 b=read('scripts/core/game_bootstrap.gd'); c=read('scripts/ui/command_deck.gd'); assert 'M271TargetingRelationshipAuthorityRuntime.new()' in b and 'TargetingRelationshipAuthorityReadiness' in b; assert 'TARGETING · AGGRO · PVP · SAFE ZONES' in c and 'M271TargetingRelationshipAuthorityCatalog.legality' in c
